func:
flow.set("gridcode_rpc_response_topic", msg.rpcResponseTopic);

let operation = msg.operation || 'read';
const params = msg.rpcParams || {};

// Check if any writable field is present
if (params.gridModeRaw !== undefined ||
    params.gridFrequencyHz !== undefined ||
    params.gridVoltageLevelCode !== undefined ||
    params.normalConnect !== undefined ||
    params.reconnectionTimeSeconds !== undefined ||
    params.powerFactorTarget !== undefined ||
    params.activePowerRegulationPercentPerStep !== undefined ||
    params.reactivePowerRegulationPercentPerStep !== undefined) {
    operation = 'write';
}

msg.operation = operation;

if (operation === 'write') {
    return [null, msg];
} else {
    return [msg, null];
}

flow.set("gridcode_part_sn", null);
flow.set("gridcode_part_pf", null);
flow.set("gridcode_part_282", null);
flow.set("gridcode_part_grid", null);

return msg;

msg.readGroup = "sn";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 3,
    quantity: 5
};
return msg;

msg.readGroup = "pf";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 39,
    quantity: 3
};
return msg;

msg.readGroup = "reg282";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 282,
    quantity: 1
};
return msg;

msg.readGroup = "grid";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 284,
    quantity: 7
};
return msg;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data)) {
    node.error("Invalid response for " + msg.readGroup);
    return null;
}

const group = msg.readGroup;

if (group === "sn") {
    flow.set("gridcode_part_sn", data);
} else if (group === "pf") {
    flow.set("gridcode_part_pf", data);
} else if (group === "reg282") {
    flow.set("gridcode_part_282", data[0]);
} else if (group === "grid") {
    flow.set("gridcode_part_grid", data);
}

// Check if all parts received
const partSn = flow.get("gridcode_part_sn");
const partPf = flow.get("gridcode_part_pf");
const part282 = flow.get("gridcode_part_282");
const partGrid = flow.get("gridcode_part_grid");

if (!partSn || !partPf || part282 === null || part282 === undefined || !partGrid) {
    return null;
}

msg.snData = partSn;
msg.pfData = partPf;
msg.reg282 = part282;
msg.gridData = partGrid;
return msg;

const snData = msg.snData;
const pfData = msg.pfData;
const reg282 = msg.reg282;
const gridData = msg.gridData;

// Clear flow context
flow.set("gridcode_part_sn", null);
flow.set("gridcode_part_pf", null);
flow.set("gridcode_part_282", null);
flow.set("gridcode_part_grid", null);

// Helper: Parse ASCII
function parseAsciiChar(val, high) {
    const byte = high ? ((val >> 8) & 0xFF) : (val & 0xFF);
    if (byte >= 0x20 && byte <= 0x7E) {
        return String.fromCharCode(byte);
    }
    return '';
}

function parseSerialNumber(regs) {
    let sn = '';
    for (let i = 0; i < 5; i++) {
        sn += parseAsciiChar(regs[i], true);
        sn += parseAsciiChar(regs[i], false);
    }
    return sn.trim();
}

const serialNumber = parseSerialNumber(snData);

// Parse PF data (039-041)
const reg39 = pfData[0];  // Power factor (0-2000, offset +1000)
const reg40 = pfData[1];  // Active power regulation (0.1%)
const reg41 = pfData[2];  // Reactive power regulation (0.1%)

const powerFactorTarget = reg39;  // Keep raw, offset applied externally
const activePowerReg = reg40 * 0.1;
const reactivePowerReg = reg41 * 0.1;

// Parse 282
const reconnectionTimeSeconds = reg282;

// Parse grid data (284-290)
const reg284 = gridData[0];  // Grid Mode
const reg285 = gridData[1];  // Grid Frequency
const reg286 = gridData[2];  // Grid Type
const reg287 = gridData[3];  // Grid Vol High (0.1V)
const reg288 = gridData[4];  // Grid Vol Low (0.1V)
const reg289 = gridData[5];  // Grid Hz High (0.01Hz)
const reg290 = gridData[6];  // Grid Hz Low (0.01Hz)

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";

const state = {
    kind: "GridCodeConfigState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: serialNumber,
    version: "1.0",

    gridModeRaw: reg284,
    gridFrequencyHz: reg285 === 0 ? 50 : 60,
    gridVoltageLevelCode: reg286,

    normalConnect: {
        voltageLowV: reg288 * 0.1,
        voltageHighV: reg287 * 0.1,
        frequencyLowHz: reg290 * 0.01,
        frequencyHighHz: reg289 * 0.01
    },

    reconnectionTimeSeconds: reconnectionTimeSeconds,

    powerFactorTarget: powerFactorTarget,
    activePowerRegulationPercentPerStep: Math.round(activePowerReg * 10) / 10,
    reactivePowerRegulationPercentPerStep: Math.round(reactivePowerReg * 10) / 10,

    rawRegisters: {
        reg39: reg39,
        reg40: reg40,
        reg41: reg41,
        reg282: reg282,
        reg284: reg284,
        reg285: reg285,
        reg286: reg286,
        reg287: reg287,
        reg288: reg288,
        reg289: reg289,
        reg290: reg290
    }
};

// Check if this is after a write
const writeResult = flow.get("gridcode_write_result");
flow.set("gridcode_write_result", null);

const rpcResponseTopic = flow.get("gridcode_rpc_response_topic");
flow.set("gridcode_rpc_response_topic", null);

if (writeResult) {
    msg.payload = {
        success: true,
        message: `Successfully wrote ${writeResult.count} register(s)`,
        writes: writeResult.writes,
        state: state
    };
} else {
    msg.payload = state;
}

msg.rpcResponseTopic = rpcResponseTopic;

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;

const params = msg.rpcParams || {};
const writes = [];

// 039: powerFactorTarget (0-2000)
if (params.powerFactorTarget !== undefined) {
    const val = Math.max(0, Math.min(2000, params.powerFactorTarget));
    writes.push({ register: 39, value: val, name: "Power Factor Target" });
}

// 040: activePowerRegulationPercentPerStep (0.1% scale)
if (params.activePowerRegulationPercentPerStep !== undefined) {
    const val = Math.round(params.activePowerRegulationPercentPerStep * 10);
    writes.push({ register: 40, value: val, name: "Active Power Reg" });
}

// 041: reactivePowerRegulationPercentPerStep (0.1% scale)
if (params.reactivePowerRegulationPercentPerStep !== undefined) {
    const val = Math.round(params.reactivePowerRegulationPercentPerStep * 10);
    writes.push({ register: 41, value: val, name: "Reactive Power Reg" });
}

// 282: reconnectionTimeSeconds (10-300)
if (params.reconnectionTimeSeconds !== undefined) {
    const val = Math.max(10, Math.min(300, params.reconnectionTimeSeconds));
    writes.push({ register: 282, value: val, name: "Reconnection Time" });
}

// 284: gridModeRaw
if (params.gridModeRaw !== undefined) {
    writes.push({ register: 284, value: params.gridModeRaw, name: "Grid Mode" });
}

// 285: gridFrequencyHz (0=50Hz, 1=60Hz)
if (params.gridFrequencyHz !== undefined) {
    const val = params.gridFrequencyHz === 60 ? 1 : 0;
    writes.push({ register: 285, value: val, name: "Grid Frequency" });
}

// 286: gridVoltageLevelCode
if (params.gridVoltageLevelCode !== undefined) {
    writes.push({ register: 286, value: params.gridVoltageLevelCode, name: "Grid Voltage Level" });
}

// normalConnect object
if (params.normalConnect) {
    const nc = params.normalConnect;

    // 287: voltageHighV (0.1V scale)
    if (nc.voltageHighV !== undefined) {
        const val = Math.round(nc.voltageHighV * 10);
        writes.push({ register: 287, value: val, name: "Voltage High" });
    }

    // 288: voltageLowV (0.1V scale)
    if (nc.voltageLowV !== undefined) {
        const val = Math.round(nc.voltageLowV * 10);
        writes.push({ register: 288, value: val, name: "Voltage Low" });
    }

    // 289: frequencyHighHz (0.01Hz scale)
    if (nc.frequencyHighHz !== undefined) {
        const val = Math.round(nc.frequencyHighHz * 100);
        writes.push({ register: 289, value: val, name: "Frequency High" });
    }

    // 290: frequencyLowHz (0.01Hz scale)
    if (nc.frequencyLowHz !== undefined) {
        const val = Math.round(nc.frequencyLowHz * 100);
        writes.push({ register: 290, value: val, name: "Frequency Low" });
    }
}

if (writes.length === 0) {
    node.warn("No valid parameters to write");
    return null;
}

global.set("gridcode_write_queue", writes);
global.set("gridcode_write_index", 0);
global.set("gridcode_write_results", []);

node.status({ fill: "blue", shape: "dot", text: writes.length + " writes queued" });

return msg;

const writes = global.get("gridcode_write_queue") || [];
const index = global.get("gridcode_write_index") || 0;

if (index >= writes.length) {
    return null;
}

const current = writes[index];

msg.payload = {
    fc: 16,
    unitid: 1,
    address: current.register,
    quantity: 1,
    value: [current.value]
};
msg.currentWrite = current;

node.status({ fill: "blue", shape: "dot", text: `[${index+1}/${writes.length}] ${current.name}` });

return msg;

const writes = global.get("gridcode_write_queue") || [];
let index = global.get("gridcode_write_index") || 0;
const results = global.get("gridcode_write_results") || [];

const current = msg.currentWrite;
if (current) {
    results.push({
        register: current.register,
        name: current.name,
        value: current.value,
        success: true
    });
    global.set("gridcode_write_results", results);
}

index++;
global.set("gridcode_write_index", index);

node.status({ fill: "green", shape: "dot", text: `${current.name} OK` });

if (index < writes.length) {
    return [msg, null];
}

// All writes done
flow.set("gridcode_write_result", {
    count: results.length,
    writes: results
});

global.set("gridcode_write_queue", null);
global.set("gridcode_write_index", null);
global.set("gridcode_write_results", null);

return [null, msg];
